"""RED metadata contract for passive service lifecycle execution readiness."""
from __future__ import annotations
from dataclasses import is_dataclass
import pytest
from engine.phase_12_passive_service_lifecycle_execution_readiness_design_contract_v1 import (
 PassiveLifecycleExecutionReadinessPolicyV1,PassiveLifecycleExecutionReadinessIdentityV1,PassiveCliExecutionReadinessEvidenceV1,HostSignalExecutionReadinessEvidenceV1,GracefulShutdownExecutionReadinessEvidenceV1,HandlerRestorationExecutionReadinessEvidenceV1,ProcessExitExecutionReadinessEvidenceV1,SystemdServiceLifecycleReadinessEvidenceV1,CredentialOnboardingReadinessEvidenceV1,ProviderBudgetGateReadinessEvidenceV1,ProductionExecutionReadinessChecklistV1,ProductionExecutionOperatorAttestationV1,ProductionExecutionIndependentReviewerApprovalV1,PassiveLifecycleExecutionReadinessFailureV1,PassiveLifecycleExecutionReadinessDecisionV1,PassiveLifecycleExecutionReadinessAuditEvidenceV1,evaluate_passive_lifecycle_execution_readiness_design_v1,compose_passive_lifecycle_execution_readiness_without_execution_v1,build_passive_lifecycle_execution_readiness_audit_evidence_v1)
def _frozen(x:object)->None:
 assert is_dataclass(x);assert type(x).__dataclass_params__.frozen;assert "__dict__" not in type(x).__slots__
def _policy(**o:object)->PassiveLifecycleExecutionReadinessPolicyV1:
 v=dict(policy_id="execution-readiness-v1",policy_version="V1",passive_lifecycle_execution_readiness_design_authorized=True,passive_cli_execution_readiness_design_authorized=True,host_signal_execution_readiness_design_authorized=True,graceful_shutdown_execution_readiness_design_authorized=True,handler_restoration_execution_readiness_design_authorized=True,process_exit_execution_readiness_design_authorized=True,systemd_service_lifecycle_readiness_design_authorized=True,credential_onboarding_readiness_composition_design_authorized=True,provider_budget_gate_readiness_composition_design_authorized=True,production_execution_evidence_package_design_authorized=True,metadata_only_readiness_evaluation=True,caller_supplied_evidence_only=True,independent_review_required=True,all_operational_authorities_must_remain_false=True,all_gates_must_remain_closed=True,deployment_must_remain_blocked=True,fail_closed=True,passive_lifecycle_execution_implementation_authorized=False,passive_cli_execution_authorized=False,passive_launcher_execution_authorized=False,component_adapter_invocation_authorized=False,production_service_execution_authorized=False,production_runtime_execution_authorized=False,credential_loading_authorized=False,credential_value_access_authorized=False,systemd_access_authorized=False,provider_transmission_authorized=False,activation_gate_open=False,credential_gate_open=False,network_gate_open=False,workload_gate_open=False)
 return PassiveLifecycleExecutionReadinessPolicyV1(**(v|o))
def test_public_contract_is_immutable_slotted_and_design_only()->None:
 for r in (_policy(),PassiveLifecycleExecutionReadinessIdentityV1(readiness_id="r",service_unit="ai-crypto-signal-agent.service")): _frozen(r)
 for t in (PassiveCliExecutionReadinessEvidenceV1,HostSignalExecutionReadinessEvidenceV1,GracefulShutdownExecutionReadinessEvidenceV1,HandlerRestorationExecutionReadinessEvidenceV1,ProcessExitExecutionReadinessEvidenceV1,SystemdServiceLifecycleReadinessEvidenceV1,CredentialOnboardingReadinessEvidenceV1,ProviderBudgetGateReadinessEvidenceV1,ProductionExecutionReadinessChecklistV1,ProductionExecutionOperatorAttestationV1,ProductionExecutionIndependentReviewerApprovalV1,PassiveLifecycleExecutionReadinessFailureV1,PassiveLifecycleExecutionReadinessDecisionV1,PassiveLifecycleExecutionReadinessAuditEvidenceV1):assert hasattr(t,"__dataclass_fields__")
@pytest.mark.parametrize(("p","code"),((_policy(passive_lifecycle_execution_readiness_design_authorized=False),"PASSIVE_LIFECYCLE_EXECUTION_READINESS_DESIGN_NOT_AUTHORIZED"),(_policy(credential_loading_authorized=True),"CREDENTIAL_LOADING_NOT_AUTHORIZED"),(_policy(network_gate_open=True),"NETWORK_GATE_MUST_REMAIN_CLOSED")))
def test_authority_escalation_fails_closed(p:PassiveLifecycleExecutionReadinessPolicyV1,code:str)->None:
 d=evaluate_passive_lifecycle_execution_readiness_design_v1(policy=p,evidence=())
 assert d.ready is False;assert code in d.failure_codes
def test_production_execution_stays_blocked_pending_owner_secret_entry()->None:
 d=evaluate_passive_lifecycle_execution_readiness_design_v1(policy=_policy(),evidence=("ACCEPTED_BOUNDARIES_GREEN",))
 assert d.production_execution_classification=="BLOCKED_PENDING_OWNER_SECRET_ENTRY_AND_SEPARATE_EXECUTION_AUTHORIZATION"
 assert d.owner_secret_entry_executed is False;assert d.api_key_entered is False;assert d.credential_gate_open is False
 c=compose_passive_lifecycle_execution_readiness_without_execution_v1(decision=d,composition_id="c")
 assert not isinstance(c,int);assert c.service_executed is False;assert c.production_runtime_executed is False
 e=build_passive_lifecycle_execution_readiness_audit_evidence_v1(evidence_id="e",decision=d,composition=c);_frozen(e);assert "0x" not in repr(e)
